      "tooltip": "Systemic resilience is like a gear, it shows how decentralized components interlock to create a stable and efficient whole."
    }
  ],
  "claim_sketches": [
    {
      "claim": "Static regulatory checkpoints act as a monitorability tax, introducing latency that prevents systems from adapting to real-time grid fluctuations.",
      "targets": ["AN-31"]
    },
    {
      "claim": "The 20% efficiency gain in grid management is not a reckless gamble; it is the natural outcome of replacing slow, human-in-the-loop latency with high-frequency, resilient architectures.",
      "targets": ["AN-33"]
    },
    {
      "claim": "Reliability is a function of system speed and responsiveness, not of the intensity of human bureaucratic review.",
      "targets": ["AN-32"]
    }
  ],
  "key_assumptions": [
    {
      "assumption": "Automated, decentralized verification mechanisms can be designed to be as robust as, or more robust than, human-led oversight.",
